// ui/coreShared/js/app/lib/supportedNetworkChange.js
function createSupportedNetworkChangeCoordinator({ getInFlightCount, replaceEnvironment }) {
  let replacementPending = false;
  let replacementPromise;
  const replaceWhenSafe = () => {
    if (replacementPromise !== undefined)
      return replacementPromise;
    replacementPromise = (async () => {
      while (replacementPending && getInFlightCount() === 0) {
        replacementPending = false;
        const committed = await replaceEnvironment(() => getInFlightCount() === 0);
        if (!committed)
          replacementPending = true;
      }
    })().finally(() => {
      replacementPromise = undefined;
    });
    return replacementPromise;
  };
  const drainPendingReplacement = async () => {
    await replaceWhenSafe();
    while (replacementPending && getInFlightCount() === 0)
      await replaceWhenSafe();
  };
  return {
    handleSupportedNetworkChange: async () => {
      replacementPending = true;
      await drainPendingReplacement();
    },
    handleTransactionFinished: async () => {
      await drainPendingReplacement();
    }
  };
}

// ui/zoltar/js/features/reporting/lib/reportingForm.js
function applyReportingFormUpdate(current, update) {
  const securityPoolAddressChanged = update.securityPoolAddress !== undefined && !sameCaseInsensitiveText(current.securityPoolAddress, update.securityPoolAddress);
  const nextForm = {
    ...current,
    ...update,
    ...securityPoolAddressChanged ? {
      selectedOutcome: undefined,
      selectedWithdrawDepositIndexesByOutcome: getDefaultReportingWithdrawDepositIndexesByOutcome()
    } : {}
  };
  const hasChanged = Object.keys(update).some((key) => {
    if (key === "securityPoolAddress" && update.securityPoolAddress !== undefined)
      return securityPoolAddressChanged || !sameCaseInsensitiveText(current.securityPoolAddress, nextForm.securityPoolAddress);
    return current[key] !== nextForm[key];
  });
  if (!hasChanged && current.selectedOutcome === nextForm.selectedOutcome)
    return current;
  return nextForm;
}

